//! Scrape-time aggregation of independent worker registries.
//!
//! Registration and collection are cold paths. Recording a worker's metrics
//! never accesses this list or another worker's registry. This consumes the
//! exposition generated by our legacy and prometheus-client encoders, keeping
//! their metric names/labels without introducing a worker label.
use crate::legacy::FmtMetrics;
use parking_lot::RwLock;
use std::{
    collections::{BTreeMap, BTreeSet},
    fmt::{self, Write as _},
    sync::Arc,
};

type Report = Arc<dyn FmtMetrics + Send + Sync>;

#[derive(Clone, Default)]
pub struct Aggregate(Arc<RwLock<Vec<Report>>>);

impl Aggregate {
    /// Register once when constructing a worker. Retain reports after its
    /// tasks stop, so completed requests do not disappear from counters.
    pub fn register(&self, report: impl FmtMetrics + Send + Sync + 'static) {
        self.0.write().push(Arc::new(report));
    }

    /// Shared mode uses the original formatter unchanged. Worker mode merges
    /// the primary (control/listeners) report with the worker registries.
    pub fn with_primary<M>(&self, primary: M, enabled: bool) -> Aggregated<M> {
        Aggregated {
            primary,
            workers: self.clone(),
            enabled,
        }
    }
}

#[derive(Clone)]
pub struct Aggregated<M> {
    primary: M,
    workers: Aggregate,
    enabled: bool,
}

impl<M: FmtMetrics> FmtMetrics for Aggregated<M> {
    fn fmt_metrics(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if !self.enabled {
            return self.primary.fmt_metrics(f);
        }
        // Release the list lock before formatting any live metric. Each
        // registry's normal snapshot/retention behavior remains in force.
        let workers = self.workers.0.read().clone();
        let mut merged = Exposition::default();
        let mut text = String::new();
        write!(text, "{}", self.primary.as_display())?;
        merged.add(&text)?;
        for worker in workers {
            text.clear();
            write!(text, "{}", DisplayReport(&*worker))?;
            merged.add(&text)?;
        }
        fmt::Display::fmt(&merged, f)
    }
}

struct DisplayReport<'a>(&'a dyn FmtMetrics);
impl fmt::Display for DisplayReport<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt_metrics(f)
    }
}

#[derive(Default)]
struct Exposition {
    families: BTreeMap<String, Metadata>,
    samples: BTreeMap<Key, Value>,
    // Merging histograms with different bucket boundaries would corrupt the
    // distribution, even if their count/sum could be added.
    buckets: BTreeMap<Key, BTreeSet<String>>,
}

#[derive(Default)]
struct Metadata {
    help: Option<String>,
    kind: Option<String>,
    unit: Option<String>,
}

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
struct Key {
    name: String,
    labels: BTreeMap<String, String>,
}

struct Value {
    sum: Number,
    min: Number,
    first: Number,
    equal: bool,
    copies: usize,
    exemplar: String,
}

#[derive(Clone, Copy, Debug, PartialEq)]
enum Number {
    Int(i128),
    Float(f64),
}

impl Number {
    fn parse(text: &str) -> Result<Self, fmt::Error> {
        if let Ok(n) = text.parse() {
            return Ok(Self::Int(n));
        }
        let n = match text {
            "+Inf" | "Inf" => f64::INFINITY,
            "-Inf" => f64::NEG_INFINITY,
            _ => text.parse().map_err(|_| fmt::Error)?,
        };
        Ok(Self::Float(n))
    }

    fn float(self) -> f64 {
        match self {
            Self::Int(n) => n as f64,
            Self::Float(n) => n,
        }
    }

    fn add(self, other: Self) -> Result<Self, fmt::Error> {
        match (self, other) {
            (Self::Int(a), Self::Int(b)) => a.checked_add(b).map(Self::Int).ok_or(fmt::Error),
            _ => Ok(Self::Float(self.float() + other.float())),
        }
    }

    fn minimum(self, other: Self) -> Self {
        match (self, other) {
            (Self::Int(a), Self::Int(b)) => Self::Int(a.min(b)),
            _ => Self::Float(self.float().min(other.float())),
        }
    }
}

impl fmt::Display for Number {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Int(n) => n.fmt(f),
            Self::Float(n) if *n == f64::INFINITY => f.write_str("+Inf"),
            Self::Float(n) if *n == f64::NEG_INFINITY => f.write_str("-Inf"),
            Self::Float(n) => n.fmt(f),
        }
    }
}

fn metadata_field(slot: &mut Option<String>, value: &str) -> fmt::Result {
    if slot.as_deref().is_some_and(|old| old != value) {
        return Err(fmt::Error);
    }
    *slot = Some(value.to_owned());
    Ok(())
}

impl Exposition {
    fn add(&mut self, text: &str) -> fmt::Result {
        let mut incoming = Vec::new();
        for line in text.lines().map(str::trim).filter(|l| !l.is_empty()) {
            if let Some(comment) = line.strip_prefix("# ") {
                if comment == "EOF" {
                    continue;
                }
                let Some((field, rest)) = comment.split_once(' ') else {
                    continue;
                };
                if !matches!(field, "HELP" | "TYPE" | "UNIT") {
                    continue;
                }
                let (name, value) = rest.split_once(' ').ok_or(fmt::Error)?;
                let metadata = self.families.entry(name.to_owned()).or_default();
                let slot = match field {
                    "HELP" => &mut metadata.help,
                    "TYPE" => &mut metadata.kind,
                    "UNIT" => &mut metadata.unit,
                    _ => unreachable!(),
                };
                metadata_field(slot, value)?;
            } else if !line.starts_with('#') {
                incoming.push(parse_sample(line)?);
            }
        }
        let mut buckets: BTreeMap<Key, BTreeSet<String>> = BTreeMap::new();
        for (key, number, exemplar) in incoming {
            let family = self.family(&key.name)?;
            let kind = self.families[family].kind.as_deref();
            if kind == Some("histogram") && key.name.ends_with("_bucket") {
                let mut labels = key.labels.clone();
                let bound = labels.remove("le").ok_or(fmt::Error)?;
                buckets
                    .entry(Key {
                        name: family.to_owned(),
                        labels,
                    })
                    .or_default()
                    .insert(bound);
            }
            if let Some(value) = self.samples.get_mut(&key) {
                value.sum = value.sum.add(number)?;
                value.min = value.min.minimum(number);
                value.equal &= value.first == number;
                value.copies += 1;
            } else {
                self.samples.insert(
                    key,
                    Value {
                        sum: number,
                        min: number,
                        first: number,
                        equal: true,
                        copies: 1,
                        exemplar,
                    },
                );
            }
        }
        for (key, bounds) in buckets {
            if self.buckets.get(&key).is_some_and(|old| *old != bounds) {
                return Err(fmt::Error);
            }
            self.buckets.insert(key, bounds);
        }
        Ok(())
    }

    fn family<'a>(&'a self, name: &'a str) -> Result<&'a str, fmt::Error> {
        if self.families.contains_key(name) {
            return Ok(name);
        }
        for suffix in ["_bucket", "_count", "_sum", "_total", "_created", "_info"] {
            if let Some(base) = name.strip_suffix(suffix) {
                if self.families.contains_key(base) {
                    return Ok(base);
                }
            }
        }
        Err(fmt::Error)
    }

    fn value(&self, key: &Key, value: &Value, metadata: &Metadata) -> Result<Number, fmt::Error> {
        // Creation times are not additive; retain the earliest contributor.
        if key.name.ends_with("_created")
            && matches!(
                metadata.kind.as_deref(),
                Some("counter" | "histogram" | "summary")
            )
        {
            return Ok(value.min);
        }
        match metadata.kind.as_deref() {
            Some("counter" | "gauge" | "histogram") => Ok(value.sum),
            Some("info" | "stateset") if value.equal => Ok(value.first),
            // Quantiles cannot be combined by addition/averaging. A lone
            // primary summary is preserved, but overlapping summaries fail.
            _ if value.copies == 1 => Ok(value.first),
            _ => Err(fmt::Error),
        }
    }
}

impl fmt::Display for Exposition {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut grouped: BTreeMap<&str, Vec<(&Key, &Value)>> = BTreeMap::new();
        for (key, value) in &self.samples {
            let family = self.family(&key.name)?;
            // Validate before writing any result.
            self.value(key, value, &self.families[family])?;
            grouped.entry(family).or_default().push((key, value));
        }
        for (name, samples) in &mut grouped {
            if self.families[*name].kind.as_deref() == Some("histogram") {
                // The text format requires increasing bucket boundaries;
                // lexical order would put +Inf before finite boundaries.
                samples.sort_by(|(a, _), (b, _)| {
                    a.name
                        .cmp(&b.name)
                        .then_with(|| {
                            a.labels
                                .iter()
                                .filter(|(k, _)| *k != "le")
                                .cmp(b.labels.iter().filter(|(k, _)| *k != "le"))
                        })
                        .then_with(|| {
                            let bound = |key: &Key| {
                                key.labels
                                    .get("le")
                                    .and_then(|s| Number::parse(s).ok())
                                    .map(Number::float)
                            };
                            match (bound(a), bound(b)) {
                                (Some(a), Some(b)) => a.total_cmp(&b),
                                _ => a.labels.cmp(&b.labels),
                            }
                        })
                });
            }
        }
        for (name, metadata) in &self.families {
            if let Some(help) = &metadata.help {
                writeln!(f, "# HELP {name} {help}")?;
            }
            if let Some(kind) = &metadata.kind {
                writeln!(f, "# TYPE {name} {kind}")?;
            }
            if let Some(unit) = &metadata.unit {
                writeln!(f, "# UNIT {name} {unit}")?;
            }
            for (key, value) in grouped.get(name.as_str()).into_iter().flatten() {
                f.write_str(&key.name)?;
                if !key.labels.is_empty() {
                    f.write_char('{')?;
                    for (index, (name, label)) in key.labels.iter().enumerate() {
                        if index != 0 {
                            f.write_char(',')?;
                        }
                        write!(f, "{name}=\"")?;
                        for ch in label.chars() {
                            match ch {
                                '\\' => f.write_str("\\\\")?,
                                '"' => f.write_str("\\\"")?,
                                '\n' => f.write_str("\\n")?,
                                _ => f.write_char(ch)?,
                            }
                        }
                        f.write_char('"')?;
                    }
                    f.write_char('}')?;
                }
                write!(f, " {}", self.value(key, value, metadata)?)?;
                if !value.exemplar.is_empty() {
                    write!(f, " {}", value.exemplar)?;
                }
                f.write_char('\n')?;
            }
        }
        f.write_str("# EOF\n")
    }
}

fn parse_sample(line: &str) -> Result<(Key, Number, String), fmt::Error> {
    let end = line.find(['{', ' ', '\t']).ok_or(fmt::Error)?;
    let name = &line[..end];
    if name.is_empty() {
        return Err(fmt::Error);
    }
    let mut rest = &line[end..];
    let mut labels = BTreeMap::new();
    if let Some(after) = rest.strip_prefix('{') {
        rest = after;
        loop {
            rest = rest.trim_start();
            if let Some(after) = rest.strip_prefix('}') {
                rest = after;
                break;
            }
            let (label, after) = rest.split_once('=').ok_or(fmt::Error)?;
            let after = after.trim_start().strip_prefix('"').ok_or(fmt::Error)?;
            let mut chars = after.char_indices();
            let mut value = String::new();
            let mut closed = None;
            while let Some((offset, ch)) = chars.next() {
                match ch {
                    '"' => {
                        closed = Some(offset + 1);
                        break;
                    }
                    '\\' => value.push(match chars.next().ok_or(fmt::Error)?.1 {
                        '\\' => '\\',
                        '"' => '"',
                        'n' => '\n',
                        _ => return Err(fmt::Error),
                    }),
                    _ => value.push(ch),
                }
            }
            rest = &after[closed.ok_or(fmt::Error)?..];
            let label = label.trim();
            if label.is_empty() || labels.insert(label.to_owned(), value).is_some() {
                return Err(fmt::Error);
            }
            if let Some(after) = rest.strip_prefix(',') {
                rest = after;
            } else if let Some(after) = rest.strip_prefix('}') {
                rest = after;
                break;
            } else {
                return Err(fmt::Error);
            }
        }
    }
    if !rest.starts_with(char::is_whitespace) {
        return Err(fmt::Error);
    }
    let mut parts = rest.trim_start().splitn(2, char::is_whitespace);
    let number = Number::parse(parts.next().ok_or(fmt::Error)?)?;
    let exemplar = parts.next().unwrap_or_default().trim();
    // Built-in encoders do not emit explicit sample timestamps. Exemplars
    // may be retained from any contributing sample of the merged series.
    if !exemplar.is_empty() && !exemplar.starts_with("# {") {
        return Err(fmt::Error);
    }
    Ok((
        Key {
            name: name.to_owned(),
            labels,
        },
        number,
        exemplar.to_owned(),
    ))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::prom::{Counter, Gauge, Histogram, Registry};

    #[derive(Clone)]
    struct Text(&'static str);
    impl FmtMetrics for Text {
        fn fmt_metrics(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            f.write_str(self.0)
        }
    }

    fn render(report: impl FmtMetrics) -> Result<String, fmt::Error> {
        let mut output = String::new();
        write!(output, "{}", report.as_display())?;
        Ok(output)
    }

    fn merge(inputs: &[&str]) -> Result<String, fmt::Error> {
        let mut merged = Exposition::default();
        for input in inputs {
            merged.add(input)?;
        }
        let mut output = String::new();
        write!(output, "{merged}")?;
        Ok(output)
    }

    #[test]
    fn merges_live_independent_prometheus_registries_without_accumulating_scrapes() {
        let reports = Aggregate::default();
        let mut counters = Vec::new();
        for (count, pending, duration) in [(3, 2, 0.25), (5, 4, 0.75)] {
            let mut registry = Registry::default();
            let counter = Counter::<u64>::default();
            counter.inc_by(count);
            let gauge = Gauge::<i64>::default();
            gauge.set(pending);
            let histogram = Histogram::new([0.5, 1.0]);
            histogram.observe(duration);
            registry.register("requests", "Requests", counter.clone());
            registry.register("pending", "Pending requests", gauge);
            registry.register("duration", "Request duration", histogram);
            reports.register(crate::prom::Report::from(registry));
            counters.push(counter);
        }
        let report = reports.with_primary(Text("# EOF\n"), true);
        let first = render(&report).unwrap();
        assert!(first.contains("requests_total 8\n"));
        assert!(first.contains("pending 6\n"));
        assert!(first.contains("duration_bucket{le=\"0.5\"} 1\n"));
        assert!(first.contains("duration_bucket{le=\"+Inf\"} 2\n"));
        assert!(first.contains("duration_count 2\n"));
        assert!(first.contains("duration_sum 1\n"));
        assert!(first.find("le=\"0.5\"").unwrap() < first.find("le=\"1.0\"").unwrap());
        assert!(first.find("le=\"1.0\"").unwrap() < first.find("le=\"+Inf\"").unwrap());
        assert_eq!(first.matches("# TYPE requests counter").count(), 1);
        assert_eq!(first.matches("# EOF").count(), 1);
        assert_eq!(render(&report).unwrap(), first);
        counters[0].inc_by(2);
        assert_eq!(counters[1].get(), 5);
        assert!(render(&report).unwrap().contains("requests_total 10\n"));
    }

    #[test]
    fn shared_mode_preserves_primary_output_and_ignores_private_reports() {
        let reports = Aggregate::default();
        reports.register(Text("# TYPE x counter\nx_total 50\n# EOF\n"));
        let primary = "# TYPE x counter\nx_total 3\n# EOF\n";
        assert_eq!(
            render(reports.with_primary(Text(primary), false)).unwrap(),
            primary
        );
    }

    #[tokio::test]
    async fn admin_scrape_serves_the_aggregate_in_plain_and_gzip_formats() {
        use http_body_util::BodyExt as _;

        let reports = Aggregate::default();
        reports.register(Text("# TYPE x counter\nx_total 2\n# EOF\n"));
        let report = reports.with_primary(Text("# TYPE x counter\nx_total 3\n# EOF\n"), true);
        let serve = crate::legacy::Serve::new(report);
        let response = serve.serve(http::Request::new(())).unwrap();
        assert_eq!(response.status(), http::StatusCode::OK);
        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert_eq!(&body[..], b"# TYPE x counter\nx_total 5\n# EOF\n");

        let response = serve
            .serve(
                http::Request::builder()
                    .header(http::header::ACCEPT_ENCODING, "gzip")
                    .body(())
                    .unwrap(),
            )
            .unwrap();
        assert_eq!(response.headers()[http::header::CONTENT_ENCODING], "gzip");
        let body = response.into_body().collect().await.unwrap().to_bytes();
        assert!(body.starts_with(&[0x1f, 0x8b]));
    }

    #[test]
    fn combines_primary_legacy_counter_and_worker_counters_with_canonical_labels() {
        let output = merge(&[
            "# HELP response_total Responses\n# TYPE response_total counter\nresponse_total{direction=\"outbound\",status=\"200\"} 7\n",
            "# HELP response_total Responses\n# TYPE response_total counter\nresponse_total{status=\"200\",direction=\"outbound\"} 11\nresponse_total{status=\"503\",direction=\"outbound\"} 2\n# EOF\n",
        ]).unwrap();
        assert!(output.contains("response_total{direction=\"outbound\",status=\"200\"} 18\n"));
        assert!(output.contains("response_total{direction=\"outbound\",status=\"503\"} 2\n"));
        assert_eq!(output.matches("# TYPE response_total counter").count(), 1);
    }

    #[test]
    fn preserves_escaped_unicode_labels_and_label_identity() {
        let input = "# TYPE x counter\nx_total{path=\"한글, } \\\"quoted\\\" \\\\ \\n\"} 2\n";
        let output = merge(&[input, input]).unwrap();
        assert!(output.contains("} 4\n"));
        let key = parse_sample(output.lines().find(|l| l.starts_with("x_total")).unwrap())
            .unwrap()
            .0;
        assert_eq!(key.labels["path"], "한글, } \"quoted\" \\ \n");
    }

    #[test]
    fn sums_large_integer_counters_exactly() {
        let output = merge(&[
            "# TYPE x counter\nx_total 18446744073709551615\n",
            "# TYPE x counter\nx_total 3\n",
        ])
        .unwrap();
        assert!(output.contains("x_total 18446744073709551618\n"));
    }

    #[test]
    fn deduplicates_info_and_preserves_units_and_earliest_created_time() {
        let output = merge(&[
            "# TYPE build info\nbuild_info{version=\"a\"} 1\n# TYPE x counter\n# UNIT x seconds\nx_total 2\nx_created 20\n",
            "# TYPE build info\nbuild_info{version=\"a\"} 1\n# TYPE x counter\n# UNIT x seconds\nx_total 3\nx_created 25\n",
        ]).unwrap();
        assert!(output.contains("build_info{version=\"a\"} 1\n"));
        assert!(output.contains("x_total 5\n"));
        assert!(output.contains("x_created 20\n"));
        assert!(output.contains("# UNIT x seconds\n"));
    }

    #[test]
    fn rejects_conflicting_metadata_and_histogram_buckets() {
        assert!(merge(&["# TYPE x counter\nx_total 1\n", "# TYPE x gauge\nx 1\n"]).is_err());
        assert!(merge(&["# TYPE h histogram\nh_bucket{le=\"1\"} 1\nh_bucket{le=\"+Inf\"} 1\nh_sum 1\nh_count 1\n",
                        "# TYPE h histogram\nh_bucket{le=\"2\"} 1\nh_bucket{le=\"+Inf\"} 1\nh_sum 1\nh_count 1\n"]).is_err());
    }

    #[test]
    fn never_adds_or_averages_quantiles() {
        let input = "# TYPE latency summary\nlatency{quantile=\"0.99\"} 4\nlatency_count 1\nlatency_sum 4\n";
        assert!(merge(&[input]).is_ok());
        assert!(merge(&[input, input]).is_err());
    }

    #[test]
    fn retains_one_valid_exemplar_and_handles_special_floats() {
        let output = merge(&[
            "# TYPE h histogram\nh_sum 1 # {trace_id=\"abc\"} 1\n",
            "# TYPE h histogram\nh_sum 2\n",
        ])
        .unwrap();
        assert!(output.contains("h_sum 3 # {trace_id=\"abc\"} 1\n"));
        assert!(merge(&["# TYPE x gauge\nx +Inf\n"])
            .unwrap()
            .contains("x +Inf\n"));
        assert!(merge(&["# TYPE x gauge\nx NaN\n"])
            .unwrap()
            .contains("x NaN\n"));
    }

    #[test]
    fn concurrent_workers_keep_private_updates_and_scrapes_return_one_series() {
        let reports = Aggregate::default();
        let mut threads = Vec::new();
        for _ in 0..4 {
            let mut registry = Registry::default();
            let counter = Counter::<u64>::default();
            registry.register("requests", "Requests", counter.clone());
            reports.register(crate::prom::Report::from(registry));
            threads.push(std::thread::spawn(move || {
                for _ in 0..10_000 {
                    counter.inc();
                }
            }));
        }
        let report = reports.with_primary(Text(""), true);
        for _ in 0..5 {
            let scrape = render(&report).unwrap();
            assert_eq!(
                scrape
                    .lines()
                    .filter(|l| l.starts_with("requests_total "))
                    .count(),
                1
            );
        }
        for thread in threads {
            thread.join().unwrap();
        }
        assert!(render(&report).unwrap().contains("requests_total 40000\n"));
    }
}
